// One alert per workflow per 30 minutes; repeats in that window are counted and reported in the next alert.
const d = $input.first().json || {};
const ex = d.execution || {};
const trg = d.trigger || {};
const wf = d.workflow || {};
const wfName = String(wf.name || 'unknown workflow');
const err = ex.error || trg.error || {};
const message = String(err.message || err.description || 'No error message').slice(0, 800);
const node = String(ex.lastNodeExecuted || (err.node && err.node.name) || '-');
const url = ex.url || (ex.id ? 'https://n8n.canimi.app/workflow/' + (wf.id || '') + '/executions/' + ex.id : '');

const store = $getWorkflowStaticData('global');
store.alerts = store.alerts || {};
const now = Date.now();
const prev = store.alerts[wfName] || { last: 0, suppressed: 0 };
if (now - prev.last < 30 * 60 * 1000) {
  prev.suppressed = (prev.suppressed || 0) + 1;
  store.alerts[wfName] = prev;
  return [];
}
const suppressed = prev.suppressed || 0;
store.alerts[wfName] = { last: now, suppressed: 0 };

const when = new Date().toLocaleString('de-DE', { timeZone: 'Europe/Berlin' });
const lines = [
  'A Three To Tango workflow failed.',
  '',
  'Workflow: ' + wfName,
  'Node: ' + node,
  'Time (Berlin): ' + when,
  'Mode: ' + String(ex.mode || '-'),
  '',
  'Error:',
  message,
  '',
  url ? 'Open the execution: ' + url : 'No execution link (the trigger itself failed).',
];
if (suppressed > 0) lines.push('', 'It also failed ' + suppressed + ' more time(s) in the previous 30 minutes (no separate emails were sent).');
lines.push('', 'You get at most one email per workflow every 30 minutes.');
return [{ json: { subject: '[TTW] Workflow failed: ' + wfName, text: lines.join('\n') } }];
